-- Insert 3 example workflows to demonstrate system usage
-- These workflows show real-world scenarios for different departments

-- Get template IDs and user IDs
SET @pr_template_id = (SELECT id FROM workflow_templates WHERE workflow_type = 'PR' AND name = 'Purchase Request (PR)' LIMIT 1);
SET @budget_template_id = (SELECT id FROM workflow_templates WHERE workflow_type = 'Budget' LIMIT 1);
SET @maf_template_id = (SELECT id FROM workflow_templates WHERE workflow_type = 'MAF' LIMIT 1);

SET @requester_id = (SELECT id FROM users WHERE email = 'eddie.amintohir@compawnion.co' LIMIT 1);
SET @dept_head_id = (SELECT id FROM users WHERE department = 'PPIC' AND role != 'Staff' LIMIT 1);
SET @purchasing_id = (SELECT id FROM users WHERE department = 'Purchasing' LIMIT 1);
SET @finance_id = (SELECT id FROM users WHERE department = 'Finance' LIMIT 1);
SET @cfo_id = (SELECT id FROM users WHERE role = 'CFO' LIMIT 1);
SET @ceo_id = (SELECT id FROM users WHERE role = 'CEO' LIMIT 1);

-- ========================================
-- Example 1: Office Supplies Purchase Request
-- ========================================
SET @workflow1_id = UUID();
SET @workflow1_number = 'WFMT-PR-260223-001';

INSERT INTO workflows (
  id, workflow_number, workflow_type, template_id, title, description,
  requester_id, department, estimated_amount, currency,
  current_stage, overall_status, created_at, updated_at
)
VALUES (
  @workflow1_id,
  @workflow1_number,
  'PR',
  @pr_template_id,
  'Office Supplies Purchase - Printer Paper & Stationery',
  'Monthly office supplies procurement for PPIC department including printer paper, pens, folders, and sticky notes',
  @requester_id,
  'PPIC',
  2500000.00,
  'IDR',
  'Department Head Review',
  'in_progress',
  NOW(),
  NOW()
);

-- Create approval stages for Example 1
INSERT INTO approval_stages (id, workflow_id, stage_name, stage_order, status, assigned_to, created_at, updated_at)
VALUES
  (UUID(), @workflow1_id, 'Department Head Review', 1, 'pending', @dept_head_id, NOW(), NOW()),
  (UUID(), @workflow1_id, 'Purchasing Review', 2, 'not_started', @purchasing_id, NOW(), NOW()),
  (UUID(), @workflow1_id, 'Finance Review', 3, 'not_started', @finance_id, NOW(), NOW()),
  (UUID(), @workflow1_id, 'CFO Approval', 4, 'not_started', @cfo_id, NOW(), NOW());

-- ========================================
-- Example 2: Marketing Campaign Budget Request
-- ========================================
SET @workflow2_id = UUID();
SET @workflow2_number = 'WFMT-Budget-260223-001';
SET @marketing_head_id = (SELECT id FROM users WHERE department = 'Marketing' LIMIT 1);

INSERT INTO workflows (
  id, workflow_number, workflow_type, template_id, title, description,
  requester_id, department, estimated_amount, currency,
  current_stage, overall_status, created_at, updated_at
)
VALUES (
  @workflow2_id,
  @workflow2_number,
  'Budget',
  @budget_template_id,
  'Q1 2026 Digital Marketing Campaign Budget',
  'Budget request for Q1 digital marketing campaign including social media ads, Google Ads, and influencer partnerships. Expected ROI: 3.5x',
  @requester_id,
  'Marketing',
  50000000.00,
  'IDR',
  'Department Head Review',
  'in_progress',
  NOW(),
  NOW()
);

-- Create approval stages for Example 2
INSERT INTO approval_stages (id, workflow_id, stage_name, stage_order, status, assigned_to, created_at, updated_at)
VALUES
  (UUID(), @workflow2_id, 'Department Head Review', 1, 'pending', @marketing_head_id, NOW(), NOW()),
  (UUID(), @workflow2_id, 'Finance Review', 2, 'not_started', @finance_id, NOW(), NOW()),
  (UUID(), @workflow2_id, 'CFO Approval', 3, 'not_started', @cfo_id, NOW(), NOW()),
  (UUID(), @workflow2_id, 'CEO Final Approval', 4, 'not_started', @ceo_id, NOW(), NOW());

-- ========================================
-- Example 3: Production Material Authorization
-- ========================================
SET @workflow3_id = UUID();
SET @workflow3_number = 'WFMT-MAF-260223-001';
SET @production_head_id = (SELECT id FROM users WHERE department = 'Production' LIMIT 1);
SET @ppic_id = (SELECT id FROM users WHERE department = 'PPIC' LIMIT 1);

INSERT INTO workflows (
  id, workflow_number, workflow_type, template_id, title, description,
  requester_id, department, estimated_amount, currency,
  current_stage, overall_status, created_at, updated_at
)
VALUES (
  @workflow3_id,
  @workflow3_number,
  'MAF',
  @maf_template_id,
  'Raw Material Authorization - Steel Sheets for Product Line A',
  'Authorization to withdraw 500kg of steel sheets from warehouse for Product Line A production batch #2026-02-001. Estimated completion: March 15, 2026',
  @requester_id,
  'Production',
  15000000.00,
  'IDR',
  'Department Head Review',
  'in_progress',
  NOW(),
  NOW()
);

-- Create approval stages for Example 3
INSERT INTO approval_stages (id, workflow_id, stage_name, stage_order, status, assigned_to, created_at, updated_at)
VALUES
  (UUID(), @workflow3_id, 'Department Head Review', 1, 'pending', @production_head_id, NOW(), NOW()),
  (UUID(), @workflow3_id, 'PPIC Review', 2, 'not_started', @ppic_id, NOW(), NOW()),
  (UUID(), @workflow3_id, 'Finance Review', 3, 'not_started', @finance_id, NOW(), NOW()),
  (UUID(), @workflow3_id, 'CFO Approval', 4, 'not_started', @cfo_id, NOW(), NOW());

-- Add comments to example workflows for demonstration
INSERT INTO workflow_comments (id, workflow_id, user_id, comment_text, created_at)
VALUES
  (UUID(), @workflow1_id, @requester_id, 'Urgent: We are running low on printer paper. Please expedite approval.', NOW()),
  (UUID(), @workflow2_id, @requester_id, 'Campaign timeline: Launch date March 1st. Budget needs approval by Feb 25th to secure ad slots.', NOW()),
  (UUID(), @workflow3_id, @requester_id, 'Production schedule requires material by Feb 28th to meet customer delivery deadline.', NOW());

